$before = random(40, 60, 0.10); Context("Currency")->flags->set(trimTrailingZeros => 1); $after = Currency($before*1.2); $proposed_solution = (random(0,1)) ? $before : $before + non_zero_random(-10, 10, 0.5); $proposed_bill = Currency($proposed_solution); $left = Formula("x + 0.2x"); $right = Formula($after->value); Context("LimitedNumeric"); $lefteval = Real($left->eval(x => $proposed_solution)); $righteval = Real($right->eval(x => $proposed_solution)); $dropdown = DropDown( ["Yes, it is a solution.", "No, it is not a solution."], ($lefteval == $righteval) ? 0 : 1, showInStatic => 0 );
